#!/usr/bin/env node
// Parses docs/rubric/SOC2_CODEBASE_RUBRIC.md into src/engine/criteria.generated.ts.
// The rubric is the source of truth; never hand-edit the generated file.
// Usage: node scripts/gen-criteria.mjs [--check]
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const rubricPath = join(root, 'docs/rubric/SOC2_CODEBASE_RUBRIC.md');
const outPath = join(root, 'src/engine/criteria.generated.ts');

export function parseRubric(md) {
  const lines = md.split('\n');
  const criteria = [];
  let group = '';
  let current = null;
  let listKind = null;

  const categoryOf = (id) =>
    id.startsWith('CC')
      ? 'security'
      : id.startsWith('PI')
        ? 'processing-integrity'
        : id.startsWith('A')
          ? 'availability'
          : id.startsWith('C')
            ? 'confidentiality'
            : 'privacy';

  for (const line of lines) {
    const groupMatch = /^## (CC\d) — (.+)$/.exec(line);
    if (groupMatch) group = `${groupMatch[1]} — ${groupMatch[2]}`;
    const partMatch = /^# PART \d — ([A-Z ]+?)(?: \*\(optional category\)\*)?$/.exec(line);
    if (partMatch && !partMatch[1].startsWith('SECURITY')) {
      group = partMatch[1]
        .trim()
        .toLowerCase()
        .replace(/\b\w/g, (c) => c.toUpperCase());
    }
    if (/^# Appendix/.test(line)) break;

    const head = /^### ((?:CC|PI|A|C|P)\d+\.\d+) — (.+?)((?: `[A-Z]+`)+)\s*$/.exec(line);
    if (head) {
      current = {
        id: head[1],
        title: head[2].trim(),
        category: categoryOf(head[1]),
        group,
        tags: [...head[3].matchAll(/`([A-Z]+)`/g)].map((m) => m[1]),
        requirement: '',
        checks: [],
        checksAreSignals: false,
        redFlags: '',
        evidence: '',
        defaultManual: false,
      };
      criteria.push(current);
      listKind = null;
      continue;
    }
    if (!current) continue;

    const req = /^\*\*Requirement:\*\* (.+)$/.exec(line);
    if (req) current.requirement = req[1].trim();
    if (/^\*\*Checks:\*\*/.test(line)) listKind = 'checks';
    if (/^\*\*Repo signals:\*\*/.test(line)) {
      listKind = 'checks';
      current.checksAreSignals = true;
    }
    const rf = /^\*\*Red flags:\*\* (.+)$/.exec(line);
    if (rf) current.redFlags = rf[1].trim();
    const ev = /^\*\*Evidence:\*\* (.+)$/.exec(line);
    if (ev) current.evidence = ev[1].replace(/\s*Default:.*$/, '').trim();
    if (/Default:\s*\*{0,2}MANUAL/.test(line)) current.defaultManual = true;

    const item = /^- \[ \] (.+)$/.exec(line);
    if (item && listKind === 'checks') {
      let text = item[1].trim();
      const orgOnly = /\(`ORG`\)\s*$/.test(text);
      text = text.replace(/\s*\(`ORG`\)\s*$/, '');
      current.checks.push({ text, org: orgOnly });
    }
  }
  for (const c of criteria) {
    if (c.tags.length === 1 && c.tags[0] === 'ORG') c.defaultManual = true;
  }
  return criteria;
}

function render(criteria) {
  const body = JSON.stringify(criteria, null, 2);
  return `// GENERATED by scripts/gen-criteria.mjs from docs/rubric/SOC2_CODEBASE_RUBRIC.md.
// Do not edit by hand. Run \`npm run gen:criteria\` after changing the rubric.
import type { CriterionDef } from './types.js';

export const CRITERIA: readonly CriterionDef[] = ${body} as const satisfies readonly CriterionDef[];
`;
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const criteria = parseRubric(readFileSync(rubricPath, 'utf8'));
  if (criteria.length !== 61) {
    console.error(`Expected 61 criteria in the rubric, parsed ${criteria.length}.`);
    process.exit(1);
  }
  const out = render(criteria);
  if (process.argv.includes('--check')) {
    const existing = readFileSync(outPath, 'utf8');
    if (existing !== out) {
      console.error(
        'criteria.generated.ts is out of date with the rubric. Run npm run gen:criteria.',
      );
      process.exit(1);
    }
    console.log('criteria.generated.ts is up to date.');
  } else {
    writeFileSync(outPath, out);
    console.log(`Wrote ${criteria.length} criteria to ${outPath}`);
  }
}
